 $serialFields=@('Provider Name','Risk Pool','Member ID','Future PCP Visits 2026','PCP Visit Dates');$hrFields=@('PCP Name','Patient First Name','Patient Last Name','DOB','Patient Insurance ID');$rpoFields=@('Epic Pcp','Cdo','Member ID','Next Acv')
 $exports=@(Get-SourceRows 'Export' $exportFields 'Provider Name' $exportAlias);Set-JobProgress $Job 15 'Loaded Export source';$quality=@(Get-SourceRows 'PtListQuality' $qualityFields 'Provider Name' $qualityAlias);Set-JobProgress $Job 28 'Loaded PtListQuality source';$dsc=@();if($dscAlias){$dsc=@(Get-SourceRows 'DiabetesScorecard' $dscFields 'Provider' $dscAlias)};Set-JobProgress $Job 40 'Loaded Diabetes Scorecard source';$serial=@();if($serialAlias){$serial=@(Get-SourceRows 'SerialScheduling' $serialFields 'Provider Name' $serialAlias)};Set-JobProgress $Job 50 'Loaded Serial Scheduling source';$rpo=@();if($rpoAlias){$rpo=@(Get-SourceRows 'RiskPopulationOutreach' $rpoFields 'Epic Pcp' $rpoAlias)};Set-JobProgress $Job 54 'Loaded Risk Population Outreach source';$hr=@();if($hrKey -and $hrAlias){$hr=@(Get-SourceRows $hrKey $hrFields 'PCP Name' $hrAlias)};Set-JobProgress $Job 58 'Loaded HR source'
 $qIndex=New-UniqueIndex $quality 'MemberID';$dIndex=New-UniqueIndex $dsc 'Member ID';$sIndex=New-UniqueIndex $serial 'Member ID';$rpoIndex=New-UniqueIndex $rpo 'Member ID';$hrIds=@{};foreach($x in $hr){$id=([string]$x.'Patient Insurance ID').Trim();if($id){$hrIds[$id]=$x}};$highIds=@{};$unmatchedHr=@{};foreach($hid in $hrIds.Keys){$hrMatches=@($exports|Where-Object{$eid=([string]$_.MemberID).Trim();$eid -eq $hid -or $eid.StartsWith($hid)});if($hrMatches.Count -eq 1){$highIds[([string]$hrMatches[0].MemberID).Trim()]=$true}elseif($hrMatches.Count -eq 0){$unmatchedHr[$hid]=$hrIds[$hid]}}
 $hedis=@('BCS','COLO','EED','GSD','CBP','OMW','KED','SPC','MAD','MAC','MAH','SUPD','COB','POLY');$patients=@();$seen=@{}
 foreach($e in $exports){$id=([string]$e.MemberID).Trim();if(!$id){continue};$seen[$id]=$true;$q=$(if($qIndex.ContainsKey($id)){$qIndex[$id]}else{$null});$d=$(if($dIndex.ContainsKey($id)){$dIndex[$id]}else{$null});$s=$(if($sIndex.ContainsKey($id)){$sIndex[$id]}else{$null})
  $open=@();$closed=@();if($q){foreach($m in $hedis){$v=([string]$q.$m).Trim();if($v -in @('Needed','Non-compliant')){$open+=$m}elseif($v -in @('Completed','Compliant')){$closed+=$m}}}
  if($d){$overrides=@{'KED'=[string]($d.KED);'EED'=[string]($d.EED);'GSD'=[string]($d.GSD);'MAD'=[string]($d.'Med Adherence DM')};foreach($m in $overrides.Keys){$v=$overrides[$m];if($v -in @('Needed','Non-compliant')){if($open -notcontains $m){$open+=$m};$closed=@($closed|Where-Object{$_ -ne $m})}elseif($v -in @('Completed','Compliant')){$open=@($open|Where-Object{$_ -ne $m});if($closed -notcontains $m){$closed+=$m}}};$egfrComplete=(ConvertTo-NumberValue $d.'% eGFR last 12 mo.') -ge 100;$uacrComplete=(ConvertTo-NumberValue $d.'% uACR last 12 mo.') -ge 100;if($egfrComplete -and $uacrComplete){$open=@($open|Where-Object{$_ -ne 'KED'});if($closed -notcontains 'KED'){$closed+='KED'}}}
  $high=$highIds.ContainsKey($id);$lastAcv=(ConvertTo-DateValue $e.'Last ACV Date');$acor=([string]$e.Payer).Trim() -eq 'ACOR';$due=$false;if($lastAcv){$due=$(if($acor){$lastAcv -le (Get-Date).AddDays(-366)}else{$lastAcv -lt (Get-Date -Day 1 -Month 1)})};$nextAcv=$null;if($rpoIndex.ContainsKey($id)){$nextAcv=ConvertTo-DateValue $rpoIndex[$id].'Next Acv'};if($nextAcv -and $nextAcv.Date -ge (Get-Date).Date){$due=$false}
  $vis=@((ConvertTo-DateValue $e.'Last QEM date with non-PCP'),(ConvertTo-DateValue $e.'Last ACV Date'),(ConvertTo-DateValue $e.'Last QEM Visit Date with any PCP in assigned TIN'))|Where-Object{$_};$last=$(if($vis){$vis|Sort-Object -Descending|Select-Object -First 1}else{$null});$serialLast=$(if($s){Get-LatestDateFromText ([string]$s.'PCP Visit Dates')}else{$null})
  $patients+=[pscustomobject][ordered]@{MemberID=$id;First=[string]$e.'First Name';Last=[string]$e.'Last Name';DOB=$(ConvertTo-DateText $e.'Date of Birth');ACOR=$acor;ACVDue=$due;Attest=((ConvertTo-NumberValue $e.'Completed Attestations')+(ConvertTo-NumberValue $e.'Incompleted Attestations')) -gt 0;OpenICD=[string]$e.'Open ICDs';NewPatient=(Test-TrueValue $e.'New Patient');OpenHedis=($open -join ', ');ClosedHedis=($closed -join ', ');HighRisk=$high;LastVisit=$last;SerialLast=$serialLast;FutureVisits=$(if($s){[string]$s.'Future PCP Visits 2026'}else{''});DSC=$d}
 }
 foreach($hid in $unmatchedHr.Keys){$x=$unmatchedHr[$hid];$patients+=[pscustomobject][ordered]@{MemberID=$hid;First=[string]$x.'Patient First Name';Last=[string]$x.'Patient Last Name';DOB=$(ConvertTo-DateText $x.DOB);ACOR=$null;ACVDue=$false;Attest=$false;OpenICD='';NewPatient=$false;OpenHedis='';ClosedHedis='';HighRisk=$true;LastVisit=$null;SerialLast=$null;FutureVisits='';DSC=$null}}
 Set-JobProgress $Job 65 'Building KPI and patient panels';$total=$patients.Count;$acorCount=@($patients|Where-Object{$_.ACOR -eq $true}).Count;$non=@($patients|Where-Object{$null -ne $_.ACOR -and $_.ACOR -eq $false}).Count
 $kpi=[ordered]@{total=$total;acor=$acorCount;nonAcor=$non;acorAcvDue=@($patients|Where-Object{$_.ACOR -eq $true -and $_.ACVDue}).Count;nonAcorAcvDue=@($patients|Where-Object{$_.ACOR -eq $false -and $_.ACVDue}).Count;newPatients=@($patients|Where-Object{$_.NewPatient}).Count;hasAttestations=@($patients|Where-Object{$_.Attest}).Count;openIcd=@($patients|Where-Object{$_.OpenICD}).Count;hasHedis=@($patients|Where-Object{$_.OpenHedis -or $_.ClosedHedis}).Count;openHedis=@($patients|Where-Object{$_.OpenHedis}).Count;highRisk=@($patients|Where-Object{$_.HighRisk}).Count}
 $openRows=@($patients|Where-Object{$_.OpenHedis}|Sort-Object Last,First|ForEach-Object{,@($_.First,$_.Last,$_.DOB,$_.OpenHedis,$(ConvertTo-DateText $_.SerialLast),$(if($_.OpenICD){$_.OpenICD}else{'0'}),$(if($_.ACOR -eq $true -and $_.ACVDue){'Yes'}else{'No'}),$(if($_.ACOR -eq $false -and $_.ACVDue){'Yes'}else{'No'}))})
 $highRows=@($patients|Where-Object{$_.HighRisk}|Sort-Object Last,First|ForEach-Object{,@($_.First,$_.Last,$_.DOB,$_.OpenHedis,$(ConvertTo-DateText $_.LastVisit),$(if($_.OpenICD){$_.OpenICD}else{'0'}),$(if($_.ACOR -eq $true -and $_.ACVDue){'Yes'}else{'No'}),$(if($_.ACOR -eq $false -and $_.ACVDue){'Yes'}else{'No'}))})
 $diabRows=@();foreach($p in $patients){$d=$p.DSC;if(!$d){continue};$metric=([string]$d.KED -eq 'Needed') -or ([string]$d.EED -eq 'Needed') -or ([string]$d.GSD -eq 'Needed') -or ([string]$d.'Med Adherence DM' -eq 'Non-compliant');$appt=(ConvertTo-DateValue $d.'Next Appt Date');if($metric -and (!$appt -or $appt -gt (Get-Date).AddMonths(3))){$diabRows+=,@($p.First,$p.Last,$p.DOB,$p.OpenHedis,$(if($appt){ConvertTo-DateText $appt}else{'Needed'}),[string]$d.'Next Appt Specialty',[string]$d.'Avg Last A1c',$(if((ConvertTo-NumberValue $d.'% eGFR last 12 mo.') -ge 100){'Completed'}else{'Needed'}),$(if((ConvertTo-NumberValue $d.'% uACR last 12 mo.') -ge 100){'Completed'}else{'Needed'}))}}
 $nonRisk=@();foreach($d in $dsc){if(([string]$d.Risk) -notmatch 'Non-Risk Population'){continue};$eyeDate=(ConvertTo-DateValue $d.'Eye Exam Date');$eye=([string]$d.'Eye Exam Gap Status' -eq 'Open') -and (!$eyeDate -or $eyeDate -le (Get-Date));$appt=(ConvertTo-DateValue $d.'Next Appt Date');$apptFlag=!$appt -or $appt -gt (Get-Date).AddMonths(3);$a1c=(ConvertTo-NumberValue $d.'Avg Last A1c') -ge 9;$egfr=(ConvertTo-NumberValue $d.'% eGFR last 12 mo.') -lt 100;$uacr=(ConvertTo-NumberValue $d.'% uACR last 12 mo.') -lt 100;if($a1c -and ($eye -or $apptFlag -or $egfr -or $uacr)){$reason=@();if($eye){$reason+='Eye exam'};if($apptFlag){$reason+='Appt needed/>3 mo'};if($a1c){$reason+='A1c >=9'};if($egfr){$reason+='eGFR needed'};if($uacr){$reason+='uACR needed'};$nonRisk+=,@([string]$d.Patient,[string]$d.'Eye Exam Gap Status',$(ConvertTo-DateText $eyeDate),$(if($appt){ConvertTo-DateText $appt}else{'Needed'}),[string]$d.'Next Appt Specialty',[string]$d.'Avg Last A1c',$(if(!$egfr){'Completed'}else{'Needed'}),$(if(!$uacr){'Completed'}else{'Needed'}),($reason -join '; '))}}
 return [ordered]@{provider=[ordered]@{displayName=$Job.displayName;npi=$Job.providerKey;riskPool=$(Get-P $Job 'riskPool' $(if($exports.Count){[string]$exports[0].'Risk Pool'}else{''}));aliases=$Job.aliases};generatedUtc=[DateTime]::UtcNow.ToString('o');kpi=$kpi;narrative=($Job.displayName+' has '+$total+' patients: '+$acorCount+' ACOR and '+$non+' non-ACOR. New patients total '+$kpi.newPatients+'; '+$kpi.hasAttestations+' have attestations and '+$kpi.openIcd+' have Open ICD content.');tables=[ordered]@{openHedis=[ordered]@{columns=@('First Name','Last Name','DOB','Open HEDIS','Last Visit','Open ICDs','PCP AWV Due','NP AWV Due');rows=$openRows};highRisk=[ordered]@{columns=@('First Name','Last Name','DOB','Open HEDIS','Last Visit','Open ICDs','PCP AWV Due','NP AWV Due');rows=$highRows};diabetes=[ordered]@{columns=@('First Name','Last Name','DOB','Open HEDIS','Next Appt Date','Next Appt Specialty','Avg Last A1c','eGFR','uACR');rows=$diabRows};nonRiskDiabetes=[ordered]@{columns=@('Patient (MRN)','Eye Exam Gap','Eye Exam Date','Next Appt Date','Next Appt Specialty','Avg Last A1c','eGFR','uACR','Reason Included');rows=$nonRisk}};warnings=@()}
}
function ConvertTo-TableHtml([string]$Id,[string]$Title,$Table,[string]$Description){$head=($Table.columns|ForEach-Object{'<th>'+ (ConvertTo-HtmlEncoded $_) +'</th>'}) -join '';$body='';foreach($row in @($Table.rows)){$cells=(@($row)|ForEach-Object{'<td>'+ (ConvertTo-HtmlEncoded $_) +'</td>'}) -join '';$body+='<tr>'+$cells+'</tr>'};if(!$body){$body='<tr><td colspan="'+$Table.columns.Count+'">No matching patients</td></tr>'};return '<section><div class="section-head"><h2>'+ (ConvertTo-HtmlEncoded $Title) +'</h2><button onclick="copyTable('''+$Id+''',this)">Copy table</button></div><p>'+ (ConvertTo-HtmlEncoded $Description) +'</p><div class="table-wrap"><table id="'+$Id+'"><thead><tr>'+$head+'</tr></thead><tbody>'+$body+'</tbody></table></div></section>'}
function ConvertTo-AnalysisHtml($Model){$k=$Model.kpi;$tiles=@('Total Patients',$k.total,'ACOR Payor',$k.acor,'Non-ACOR Payor',$k.nonAcor,'ACOR + ACV Due',$k.acorAcvDue,'Non-ACOR + ACV Due',$k.nonAcorAcvDue,'New Patients',$k.newPatients,'Has Attestations',$k.hasAttestations,'Open ICDs Present',$k.openIcd,'Has HEDIS',$k.hasHedis,'Open HEDIS Present',$k.openHedis,'High Risk',$k.highRisk);$tileHtml='';for($i=0;$i -lt $tiles.Count;$i+=2){$tileHtml+='<div class="tile"><span>'+ (ConvertTo-HtmlEncoded $tiles[$i]) +'</span><strong>'+ (ConvertTo-HtmlEncoded $tiles[$i+1]) +'</strong></div>'};$tables=(ConvertTo-TableHtml 'openHedis' 'Open HEDIS List' $Model.tables.openHedis 'Patients with one or more open HEDIS metrics; review documentation and closure opportunities.')+(ConvertTo-TableHtml 'highRisk' 'High Risk / Tuck-In Patient Panel' $Model.tables.highRisk 'Entire high-risk panel, including visit and AWV follow-up context.')+(ConvertTo-TableHtml 'diabetes' 'Diabetes Care Gap Patient Panel' $Model.tables.diabetes 'Value-based diabetes patients with an open evidence-based metric and no appointment within three months.')+(ConvertTo-TableHtml 'nonRisk' 'Non-Risk Diabetes Scorecard Follow-Up Panel' $Model.tables.nonRiskDiabetes 'Non-risk patients with A1c at least 9.0 and at least one additional follow-up need.');$generated=([DateTime]$Model.generatedUtc).ToLocalTime().ToString('g')
 return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+ (ConvertTo-HtmlEncoded $Model.provider.displayName) +' - Provider Analysis</title><style>body{font:14px Segoe UI,Arial;margin:0;background:#f4f7fb;color:#172033}header{background:#17365d;color:#fff;padding:28px}main{max-width:1500px;margin:auto;padding:24px}.meta{color:#d9e6f5}.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.tile,section{background:#fff;border:1px solid #dce4ef;border-radius:8px;padding:16px}.tile span{display:block;color:#667085;font-size:12px;text-transform:uppercase}.tile strong{font-size:28px;color:#17365d}.story{font-size:17px}.section-head{display:flex;justify-content:space-between;align-items:center}button{background:#1769aa;color:#fff;border:0;border-radius:5px;padding:8px 12px;cursor:pointer}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%}th,td{padding:8px;border-bottom:1px solid #dde4ed;text-align:left;white-space:nowrap}th{background:#eaf1f8}section{margin-top:18px}@media print{button{display:none}body{background:#fff}section{break-inside:avoid}}</style></head><body><header><h1>Provider Patient Dashboard</h1><h2>'+ (ConvertTo-HtmlEncoded $Model.provider.displayName) +'</h2><div class="meta">NPI '+(ConvertTo-HtmlEncoded $Model.provider.npi)+' | Generated '+(ConvertTo-HtmlEncoded $generated)+'</div></header><main><div class="tiles">'+$tileHtml+'</div><section><h2>Story in Brief</h2><p class="story">'+(ConvertTo-HtmlEncoded $Model.narrative)+'</p></section>'+$tables+'</main><script>function copyTable(id,btn){const t=document.getElementById(id),text=[...t.rows].map(r=>[...r.cells].map(c=>c.innerText).join("\t")).join("\n");let ok=false,box=null;try{box=document.createElement("div");box.contentEditable="true";box.style.position="fixed";box.style.left="-10000px";box.style.top="0";box.style.background="white";box.appendChild(t.cloneNode(true));document.body.appendChild(box);const range=document.createRange();range.selectNodeContents(box);const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);ok=document.execCommand("copy");sel.removeAllRanges()}catch(e){}finally{if(box)box.remove()}if(ok){btn.textContent="Copied";setTimeout(()=>btn.textContent="Copy table",1600);return}const fallback=()=>{const a=document.createElement("textarea");a.value=text;a.style.position="fixed";a.style.left="-10000px";document.body.appendChild(a);a.focus();a.select();let done=false;try{done=document.execCommand("copy")}catch(e){}a.remove();btn.textContent=done?"Copied as text":"Copy failed";setTimeout(()=>btn.textContent="Copy table",1600)};if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(()=>{btn.textContent="Copied as text";setTimeout(()=>btn.textContent="Copy table",1600)}).catch(fallback)}else{fallback()}}</script></body></html>'
}
function Convert-HtmlPdf([string]$HtmlPath,[string]$PdfPath){$candidates=@("$env:ProgramFiles (x86)\Microsoft\Edge\Application\msedge.exe","$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe","$env:ProgramFiles\Google\Chrome\Application\chrome.exe","$env:ProgramFiles (x86)\Google\Chrome\Application\chrome.exe");$browser=@($candidates|Where-Object{Test-Path $_})[0];if(!$browser){throw 'Microsoft Edge or Google Chrome is required for PDF output.'};$uri=([Uri]$HtmlPath).AbsoluteUri;$stdout=$PdfPath+'.browser.out';$stderr=$PdfPath+'.browser.err';try{$p=Start-Process -FilePath $browser -ArgumentList @('--headless','--disable-gpu','--disable-logging','--log-level=3','--no-first-run','--no-default-browser-check',('--print-to-pdf='+$PdfPath),$uri) -RedirectStandardOutput $stdout -RedirectStandardError $stderr -WindowStyle Hidden -PassThru -Wait;if($p.ExitCode -ne 0 -or !(Test-Path $PdfPath)){throw 'Browser PDF rendering failed.'}}finally{Remove-Item $stdout,$stderr -Force -ErrorAction SilentlyContinue}}
function Invoke-AnalysisJob([string]$JobId){$path=Join-Path $script:Paths.State ('job-'+$JobId+'.json');$job=Json $path;if(!$job){throw 'Analysis job was not found.'};try{Set-JobProgress $job 5 'Starting analysis worker';Set-P $job 'startedUtc' ([DateTime]::UtcNow.ToString('o'));Save-JsonAtomic $path $job;$model=New-ProviderAnalysis $job;Set-JobProgress $job 72 'Rendering HTML dashboard';$slug=ConvertTo-ProviderSlug ([string]$job.displayName);$base=$slug+'__'+[string]$job.providerKey+'__analysis__current';$stageHtml=Join-Path $script:Paths.Staging ($JobId+'.html');$stagePdf=Join-Path $script:Paths.Staging ($JobId+'.pdf');$jsonPath=Join-Path $script:Paths.State ('analysis-'+$JobId+'.json');Save-JsonAtomic $jsonPath $model;[IO.File]::WriteAllText($stageHtml,(ConvertTo-AnalysisHtml $model),(New-Object Text.UTF8Encoding($false)));Set-JobProgress $job 82 'Rendering PDF';Convert-HtmlPdf $stageHtml $stagePdf;Set-JobProgress $job 92 'Publishing current outputs';$archiveDir=Join-Path $script:Paths.ProvidersArchive $slug;if(!(Test-Path $archiveDir)){New-Item -ItemType Directory -Path $archiveDir -Force|Out-Null};$currentHtml=Join-Path $script:Paths.ProvidersCurrent ($base+'.html');$currentPdf=Join-Path $script:Paths.ProvidersCurrent ($base+'.pdf');$stamp=Get-Date -Format 'yyyyMMdd-HHmmss';foreach($old in @($currentHtml,$currentPdf)){if(Test-Path $old){$ext=[IO.Path]::GetExtension($old);Move-Item $old (Join-Path $archiveDir ($slug+'__'+$job.providerKey+'__analysis__'+$stamp+$ext)) -Force}};Move-Item $stageHtml $currentHtml -Force;Move-Item $stagePdf $currentPdf -Force;$job.state='Completed';$job.percent=100;$job.stage='Analysis complete';Set-P $job 'completedUtc' ([DateTime]::UtcNow.ToString('o'));Set-P $job 'htmlPath' $currentHtml;Set-P $job 'pdfPath' $currentPdf;Set-P $job 'htmlUrl' ('/html?jobId='+$JobId);Set-P $job 'pdfUrl' ('/pdf?jobId='+$JobId);Save-JsonAtomic $path $job;Log 'ANALYSIS_COMPLETED' 'OK' ('Job '+$JobId)}catch{$job.state='Failed';$job.stage='Analysis failed';Set-P $job 'errorSummary' $_.Exception.Message;Set-P $job 'completedUtc' ([DateTime]::UtcNow.ToString('o'));Save-JsonAtomic $path $job;Log 'ANALYSIS_FAILED' 'FAILED' ($JobId+' '+$_.Exception.Message)}}
function Invoke-NextPendingJob{$jobs=@(Get-Jobs);if(@($jobs|Where-Object{$_.state -in @('Starting','Running')}).Count -gt 0){return};$j=@($jobs|Where-Object{$_.state -eq 'Prepared' -or $_.state -eq 'Queued'}|Sort-Object queuedUtc|Select-Object -First 1);if($j.Count -ne 1){return};$job=$j[0];$job.state='Starting';$job.percent=1;$job.stage='Launching background analysis worker';$jobPath=Join-Path $script:Paths.State ('job-'+$job.jobId+'.json');Save-JsonAtomic $jobPath $job;$exe=(Get-Process -Id $PID).Path;$out=Join-Path $script:Paths.Logs ('worker-'+$job.jobId+'.out.log');$err=Join-Path $script:Paths.Logs ('worker-'+$job.jobId+'.err.log');try{$quotedScript='"'+$PSCommandPath+'"';$p=Start-Process -FilePath $exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$quotedScript,'-RunJobId',$job.jobId,'-NoBrowser') -RedirectStandardOutput $out -RedirectStandardError $err -WindowStyle Hidden -PassThru;Set-P $job 'workerPid' $p.Id;Save-JsonAtomic $jobPath $job}catch{$job.state='Failed';$job.stage='Worker launch failed';Set-P $job 'errorSummary' $_.Exception.Message;Save-JsonAtomic $jobPath $job}};function Invoke-PendingJobs{while(@(Get-Jobs|Where-Object{$_.state -eq 'Prepared' -or $_.state -eq 'Queued'}).Count -gt 0){Invoke-NextPendingJob;Start-Sleep -Milliseconds 500}}
function Send-JobOutput($Context,[string]$JobId,[string]$Type){if($JobId -notmatch '^[a-f0-9]{32}$'){throw 'Invalid job ID.'};$job=Json (Join-Path $script:Paths.State ('job-'+$JobId+'.json'));if(!$job){throw 'Job not found.'};$path=$(if($Type -eq 'pdf'){Get-P $job 'pdfPath' ''}else{Get-P $job 'htmlPath' ''});if(!$path -or !(Test-Path $path)){throw 'Output is not available.'};$bytes=[IO.File]::ReadAllBytes($path);$Context.Response.StatusCode=200;$Context.Response.ContentType=$(if($Type -eq 'pdf'){'application/pdf'}else{'text/html; charset=utf-8'});$Context.Response.Headers['Content-Disposition']='inline; filename="'+[IO.Path]::GetFileName($path)+'"';$Context.Response.ContentLength64=$bytes.Length;$Context.Response.Headers['Cache-Control']='no-store';$Context.Response.OutputStream.Write($bytes,0,$bytes.Length);$Context.Response.Close()}
function Initialize-AnalysisJobRecovery{$script:RunNext=$false;foreach($f in Get-ChildItem $script:Paths.State -Filter 'job-*.json' -File -ErrorAction SilentlyContinue){$j=Json $f.FullName;if(!$j){continue};$state=[string](Get-P $j 'state' '');$err=[string](Get-P $j 'errorSummary' '');if($state -in @('Starting','Running') -or ($state -eq 'Failed' -and $err -like '*ConvertTo-NumberValue*')){$j.state='Prepared';$j.percent=0;$j.stage='Recovered after Draft 4.2 helper/queue repair';Set-P $j 'errorSummary' '';Save-JsonAtomic $f.FullName $j}}}
if($RunJobId){try{Initialize-AppFolders;Initialize-AppConfiguration;Test-ImportExcelModule;Invoke-AnalysisJob $RunJobId;exit 0}catch{Write-Error ($_.Exception.Message+' | '+$_.ScriptStackTrace);exit 1}};try{Initialize-AppFolders;Lock;Initialize-AppConfiguration;Test-ImportExcelModule;Initialize-AnalysisJobRecovery;Serve}catch{$detail=$_.Exception.Message+' | '+$_.ScriptStackTrace;try{Log 'APPLICATION' 'FAILED' $detail}catch{};Write-Error $detail;exit 1}finally{if($script:Listener){try{$script:Listener.Stop();$script:Listener.Close()}catch{}};if($script:Mutex){try{$script:Mutex.ReleaseMutex()}catch{};$script:Mutex.Dispose()};try{Log 'SERVER_STOP'}catch{}}